'use strict';
const embeddedImages={"market.jpg": "data:image/png;base64,", "period.jpg": "data:image/png;base64,", "digital.jpg": "data:image/png;base64,", "hero.jpg": "data:image/png;base64,", "esha.png": "data:image/png;base64,", "shrusti.png": "data:image/png;base64,", "olivia.png": "data:image/png;base64,"};
const siteImage=name=>embeddedImages[name]||name;
const $=s=>document.querySelector(s),app=$('#app');
let lang='zh';try{lang=localStorage.getItem('triibe-language')==='en'?'en':'zh'}catch{}
const t=(en,zh)=>lang==='zh'?zh:en;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(text,href,kind='primary')=>`<a class="btn btn-${kind}" href="${href}" ${href.startsWith('https:')?'target="_blank" rel="noopener noreferrer"':''}>${text}</a>`;
const icon=(name)=>{const paths={seed:'M12 22V12M12 16C4 17 2 12 2 7c7 0 10 3 10 9Zm0-4C12 5 16 2 23 2c0 7-4 10-11 10Z',people:'M8 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8Zm9-1a3 3 0 1 0 0-6M1 23v-4a7 7 0 0 1 14 0v4m4 0v-5a6 6 0 0 0-3-5',network:'M12 3a3 3 0 1 0 0 6 3 3 0 0 0 0-6ZM4 17a3 3 0 1 0 0 6 3 3 0 0 0 0-6Zm16 0a3 3 0 1 0 0 6 3 3 0 0 0 0-6ZM10 8l-5 9m9-9 5 9M7 20h10',money:'M2 5h21v15H2zM5 8h1m13 9h1M12 8v9m-2-7h3a2 2 0 0 1 0 4h-3m0 0v1m0-5V9',arrow:'M4 12h16m-6-6 6 6-6 6',mail:'M2 5h20v15H2ZM2 6l10 8L22 6',map:'m2 5 7-2 7 2 7-2v17l-7 2-7-2-7 2Zm7-2v17m7-15v17',refresh:'M21 8a10 10 0 1 0 1 8M21 2v7h-7',book:'M3 3h14l4 4v16H3Zm14 0v5h4M7 12h10m-10 5h10'};return `<svg viewBox="0 0 26 26" fill="none" stroke="currentColor" stroke-width="1.35" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${(paths[name]||paths.seed).split('~').map(d=>`<path d="${d}"/>`).join('')}</svg>`};
const intro=(eyebrow,title,desc)=>`<section class="page-intro"><div class="wrap"><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="lead">${desc}</p></div></section>`;
const note=()=>`<p class="small muted concept-note">${t('Student concept. Proposed support and collaboration; no funding or partnership is confirmed.','学生概念原型。资助与合作均为拟议方案，尚未确认。')}</p>`;
const support=[['money',()=>t('¥1,000–5,000','¥1,000–5,000'),()=>t('Proposed seed funding','拟议小额资助'),()=>t('Cover essential costs for your first small pilot.','为第一次小规模试点的必要开支提供支持。')],['people',()=>t('Mentorship','导师指导'),()=>t('Chinese or international','可选中国或国际导师'),()=>t('Practical feedback, with Chinese, English or bilingual preferences.','从实际问题出发，可选择中文、英文或双语指导偏好。')],['network',()=>t('Local connections','本地连接'),()=>t('Community, campus and peers','社区、高校与同伴'),()=>t('Explore partners and resources close to your idea.','寻找与你关心的问题相关的伙伴与实践资源。')]];
const supportCards=()=>`<div class="grid3">${support.map(([i,title,sub,desc])=>`<article class="support-card"><div class="line-icon">${icon(i)}</div><h3>${title()}</h3><p>${desc()}</p></article>`).join('')}</div>`;
const fourSteps=()=>`<div class="mini-steps">${[[t('Explore','探索'),t('Discover what kind of support could help your idea.','了解什么支持能帮助你的想法。')],[t('Apply','申请'),t('Share your idea through a short application.','通过简短申请，分享你想尝试的行动。')],[t('Pilot','试点'),t('Test a manageable version with guidance.','在指导下，开展可管理的小规模尝试。')],[t('Reflect','总结'),t('Learn from the experience and plan what comes next.','从实践中学习，规划适合的下一步。')]].map((s,i)=>`<div class="mini-step"><span class="step-number">0${i+1}</span><b>${s[0]}</b><p>${s[1]}</p></div>`).join('')}</div>`;
const timeline=()=>`<div class="response-timeline">${[[t('Within 5 working days','5个工作日内'),t('Initial review and reply','初步审核并回复')],[t('Within 10 working days','10个工作日内'),t('A conversation, if needed','如有需要，安排进一步沟通')],[t('Within 15 working days','15个工作日内'),t('Decision or progress update','告知结果或审核进展')]].map(([a,b])=>`<div><strong>${a}</strong><span>${b}</span></div>`).join('')}</div><p class="small muted">${t('*Proposed timing from application receipt, excluding weekends and public holidays. Demo submissions are not sent and will not receive a real reply.','*以上为自收到申请起计算的拟议时限，不含周末与法定节假日。当前演示不会实际发送申请，也不会收到真实回复。')}</p>`;
const whatsNext=()=>`<section class="section"><div class="wrap"><div class="eyebrow">${t('After your first experiment','第一次尝试之后')}</div><h2>${t('Where could<br>your next step lead?','下一步，<br>你想走向哪里？')}</h2><p class="lead">${t('A pilot opens possibilities. Choose a path based on what you learn.','试点之后有多种可能，带着真实收获选择适合你的方向。')}</p><div class="grid3 pathways">${[['refresh',t('Refine or pause','调整或暂停'),t('Keep what you learned. Change the idea, or take a break.','保留收获，调整想法，也可以暂时停下来。')],['network',t('Continue locally','在本地继续'),t('Develop a useful action with peers and community partners.','与同伴和社区伙伴一起延续有价值的行动。')],['seed',t('Grow as a founder','向发起者成长'),t('Build on the pilot and explore relevant TRIIBE opportunities.','逐步发展自己的项目，了解适合的 TRIIBE 机会。')]].map(([i,a,b])=>`<article class="path-card"><div class="line-icon">${icon(i)}</div><h3>${a}</h3><p>${b}</p>${i==='seed'?`<a class="link" href="#about">${t('Explore TRIIBE ↗','了解 TRIIBE ↗')}</a>`:''}</article>`).join('')}</div><p class="small muted">${t('Possible pathways, not automatic admission or continued funding.','以上为可能路径，不代表自动进入后续项目或持续获得资助。')}</p><div class="actions">${btn(t('Apply →','开始申请 →'),'#apply')}</div></div></section>`;
const projects=[{"id": "market", "title": ["Campus Swap Market", "校园二手市集"], "desc": ["Give useful clothes, books and everyday items a second life through swaps, gifts and low-cost sales.", "通过交换、赠送与低价交易，让衣物、书籍和生活用品继续被使用。"], "action": ["Recruit 15–20 student sellers for one market in an approved campus space. Borrow tables and rails, agree clear exchange and sales rules, and test a simple listing form.", "招募15–20位学生摊主，在获准使用的校园空间举办一次市集。优先借用桌椅和衣架，约定交换与交易规则，试用简单物品登记表。"], "learn": ["How many items find a new user? Are prices accessible, and would participants return?", "有多少件物品被再次使用？价格是否可负担？参与者是否愿意再次参加？"], "mentor": ["A mentor can help plan event operations, fair trading rules and a simple reuse evaluation. Funding supports shared logistics, not inventory bought for resale.", "导师协助活动组织、公平交易规则与再利用成效评估。资金支持公共组织开支，不用于购买转售库存。"], "rows": [[["Display supplies", "展示用品"], 1, 300, ["Reusable racks, table coverings and basic display supplies; borrow first.", "可重复使用的衣架、桌布和展示用品，优先借用。"]], [["Labels & signs", "标签与指引"], 1, 150, ["Price tags, category signs and exchange instructions.", "价格标签、分类标识及交换说明。"]], [["Essential transport", "必要运输"], 2, 150, ["Transport shared display equipment, not private purchases.", "运输公共展示设备，不补贴个人购物。"]], [["Venue setup & cleanup", "场地布置与清理"], 1, 250, ["Approved setup and reusable cleanup supplies; space assumed free.", "获准布置及可重复使用的清理用品，假设场地免费。"]]]}, {"id": "digital", "title": ["Smartphone Skills Together", "社区长者手机互助课堂"], "desc": ["Help older adults use everyday smartphone functions with more confidence.", "帮助长者更有信心地使用日常手机功能。"], "action": ["Work with a community organization to invite 8–10 older adults to two small sessions. Ask what they want to learn first, then practise basic functions on their own phones. Never handle passwords, payments or private accounts.", "与社区机构合作，邀请8–10位长者参加两次小课堂。先询问实际学习需要，再用自己的手机练习基础功能，不代管密码、支付或私人账号。"], "learn": ["Can participants complete their chosen task more independently, and are the instructions easy to follow?", "参与者能否更独立地完成所选操作？操作说明是否易读易懂？"], "mentor": ["A community or digital-inclusion mentor can help assess needs, adapt teaching and set privacy and anti-scam boundaries.", "社区或数字包容导师协助了解需求、调整教学方式，并明确隐私与防诈骗边界。"], "rows": [[["Large-print learning guides", "大字操作手册"], 20, 15, ["Ten learners, two sessions; accessible printed instructions.", "10位长者、两次活动，使用易读印刷说明。"]], [["Reusable teaching materials", "可重复使用的教学材料"], 1, 250, ["Task cards, demonstration aids and stationery; phones are participant-owned.", "任务卡、演示辅助用品与文具，不购买手机。"]], [["Essential volunteer travel", "志愿者必要交通"], 8, 40, ["Two volunteers, two sessions, return trips.", "两位志愿者、两次活动的往返出行。"]], [["Feedback & practice sheets", "反馈与练习材料"], 20, 6.5, ["Simple task sheets and anonymous feedback; community space assumed free.", "简单任务单与匿名反馈，假设社区免费提供场地。"]]]}, {"id": "period", "title": ["A Period-Friendly Campus", "经期友好校园试点"], "desc": ["Test a discreet, reliable emergency menstrual-product point on campus.", "在校园试行一个方便、体面且可靠的应急卫生用品取用点。"], "action": ["With campus approval, trial one station for 2–3 months. Use a short anonymous needs survey, assign replenishment responsibilities and track aggregate use without collecting personal health information.", "获得校方许可后，在一个地点试行2–3个月。开展简短匿名需求调查，明确补充与维护分工，仅记录总体使用情况，不收集个人健康信息。"], "learn": ["Is the point useful and easy to find? Can supplies be replenished reliably within the budget?", "取用点是否有帮助、容易找到？能否在预算内稳定补充用品？"], "mentor": ["A mentor can help with campus coordination, anonymous research, replenishment rules and a realistic continuation plan.", "导师协助校园协调、匿名需求调查、补充管理规则与可持续的后续计划。"], "rows": [[["Emergency supplies", "应急卫生用品"], 30, 20, ["Thirty packs of sealed products for an initial small trial; adapt to actual use.", "首批30包独立密封用品，按实际使用调整。"]], [["Reusable dispenser", "可重复使用的取用盒"], 1, 180, ["One accessible, easy-to-clean station at an approved location.", "在获准地点设置一个方便取用、易清洁的取用盒。"]], [["Guidance & signage", "取用指引与标识"], 1, 120, ["Clear directions and responsible-use information.", "清楚的取用及合理使用说明。"]], [["Survey & monitoring materials", "调查与记录材料"], 1, 100, ["Anonymous feedback and aggregate stock records; no personal health data.", "匿名反馈与总体库存记录，不收集个人健康信息。"]]]}];
const pt=a=>t(a[0],a[1]);
const projectCards=()=>`<div class="grid3 project-grid">${projects.map((p,i)=>`<article class="project-card" id="idea-${p.id}"><img src="${siteImage(p.id+'.jpg')}" alt="${esc(pt(p.title))}" loading="lazy"><div class="project-copy"><span class="eyebrow">0${i+1} / ${t('Illustrative pilot','假设试点')}</span><h3>${pt(p.title)}</h3><p>${pt(p.desc)}</p><details><summary>${t('Explore the experiment','看看如何尝试')}</summary><p><b>${t('First action','第一次行动')}</b><br>${pt(p.action)}</p><p>${pt(p.mentor)}</p><p><b>${t('What to learn','想了解什么')}</b><br>${pt(p.learn)}</p></details></div></article>`).join('')}</div>`;
function featuredSample(){const p=projects[0];return `<section class="section"><div class="wrap split featured-sample"><img src="${siteImage('market.jpg')}" alt="${esc(pt(p.title))}" loading="lazy"><div><div class="eyebrow">${t('Example project · Illustrative','项目示例 · 假设场景')}</div><h2>${pt(p.title)}</h2><p class="lead">${pt(p.desc)}</p><p>${pt(p.action)}</p><p class="small muted">${t('An illustrative experiment, not a verified funded project.','这是供参考的小实验，并非已核实的受资助项目。')}</p>${btn(t('Explore More Ideas →','查看更多案例 →'),'#recommendation?section=examples','outline')}</div></div></section>`}
function whyTriibe(){return `<section class="section alt"><div class="wrap split"><div><div class="eyebrow">${t('Our purpose','我们的初衷')}</div><h2>${t('Why TRIIBE?','为什么是 TRIIBE？')}</h2><p class="lead">${t('Ideas need more than inspiration. The Next Step explores how young changemakers in China can move from interest to a first experiment, with a pathway toward longer-term impact.','想法需要的不只是灵感。The Next Step探索如何帮助中国年轻人从关心一个问题，到开展第一次尝试，再逐步走向更长期的公益行动。')}</p>${btn(t('Learn About the Partners →','了解合作伙伴 →'),'#about','outline')}</div><div class="card purpose-card"><span class="pill">The Next Step</span><h3>${t('From intention to action','从想法，走向行动。')}</h3><p>${t('Small experiments, helpful people, and space to learn as you go.','小规模尝试、同行的伙伴，以及边做边学的空间。')}</p></div></div></section>`}
function home(){return `<section class="hero home-entry"><div class="wrap hero-grid"><div><div class="eyebrow">${t('For young people in China · Ages 18–30','面向中国18–30岁年轻人')}</div><h1>${t('Funding and mentorship<br>to launch your first<br>social-impact project in China.','提供资金与导师支持，<br>帮助你在中国启动<br>第一个公益项目。')}</h1><p class="lead">${t('Apply for ¥1,000–5,000 in seed funding, mentor guidance and local connections for a 2–3 month pilot. No registered organization or fully developed plan needed.','申请¥1,000–5,000启动资金、导师指导与本地资源，开展为期2–3个月的小型试点。无需已成立机构，也无需准备成熟方案。')}</p><div class="actions">${btn(t('Explore support →','了解支持 →'),'#how','outline')}${btn(t('Apply →','开始申请 →'),'#apply')}</div>${note()}</div><figure class="hero-art"><img src="${siteImage('hero.jpg')}" alt="${t('Illustration of young people planning a community project','青年一起规划社区项目的插画')}"></figure></div></section><section class="section alt"><div class="wrap"><h2>${t('Funding, mentorship and connections.','资金、导师与本地连接。')}</h2>${supportCards()}<div class="actions">${btn(t('See the Full Process →','查看完整流程 →'),'#how','outline')}</div></div></section><section class="section"><div class="wrap"><div class="section-heading"><div><h2>${t('Find your next step.','找到适合你的下一步。')}</h2></div></div><div class="grid2 next-step-grid"><article class="card"><h3>${t('Explore support','探索所需支持')}</h3><div class="actions">${btn(t('Support recommendation ↗','需求推荐 ↗'),'#recommendation','outline')}${btn(t('Budget estimator ↗','预算估算 ↗'),'#budget','outline')}</div></article><article class="card apply-card"><h3>${t('Apply with your idea','带着想法申请')}</h3>${btn(t('Apply →','开始申请 →'),'#apply')}</article></div></div></section>${whyTriibe()}`}
function how(){return `${intro(t('The journey','参与流程'),t('A small pilot.<br>A clear path.','小规模尝试，<br>清晰的参与路径。'),t('Explore support, share one idea, and learn through a 2–3 month pilot.','了解支持、分享一个想法，再用2–3个月的试点学习。'))}<section class="section compact"><div class="wrap"><div class="timeline">${[[t('01 / Initial application','01 / 初步申请'),t('Introduce yourself, your idea, current challenges and a brief estimate of support needed. No detailed budget required.','简单介绍自己、项目想法、目前困难与初步支持需求，不需要详细预算。')],[t('02 / Review & conversation','02 / 审核与沟通'),t('The project team or designated reviewers assess fit with the program, then discuss needs and feasibility with shortlisted applicants. If review takes longer, receive a progress update.','项目团队或指定评审先判断想法是否符合项目目标，再与合适的申请者沟通具体需求与可行性；如需更长时间，应告知审核进展。')],[t('03 / Mentor & budget planning','03 / 导师匹配与预算规划'),t('After initial screening, match an available mentor, refine the initial plan and agree actual funding, other support and milestones before the pilot starts.','通过初筛后匹配可用导师，共同完善初步计划，确认实际所需资金、其他支持与阶段目标，再开展试点。')],[t('04 / Try for 2–3 months','04 / 开展2–3个月试点'),t('Run a manageable experiment with kickoff, midpoint and final check-ins.','开展可管理的小实验，拟安排启动、中期和结束沟通。')],[t('05 / Reflect & choose','05 / 总结与选择'),t('Record what you learned and decide whether to refine, pause or continue.','记录学到的内容，再选择调整、暂停或继续。')]].map(([a,b])=>`<article class="timeline-body"><h3>${a}</h3><p>${b}</p></article>`).join('')}</div></div></section><section class="section compact"><div class="wrap"><div class="more-details"><h2>${t('Want to know more?','想了解更多细节？')}</h2><p class="muted">${t('Open a question to see the details.','点击问题查看说明。')}</p><details class="process-question"><summary>${t('What do reviewers look for?','评审会关注什么？')}</summary><div class="answer-body"><div class="detail-text"><h3>${t('What reviewers look for','评审会关注什么')}</h3><ul><li>${t('A clear use for funding and necessary, proportionate costs.','用途清楚，支出必要，金额与试点规模相符。')}</li><li>${t('A feasible first action and a relevant community need.','第一次行动可执行，并回应真实的社区需要。')}</li><li>${t('Readiness to work with participants, partners and a mentor.','愿意与参与者、伙伴和导师共同推进。')}</li></ul><p class="small muted">${t('“Not sure yet” is allowed. Review combines the idea, self-assessment and conversation; polished budgeting is not a prerequisite.','可以选择“还不确定”。评审结合想法、自评与沟通，不要求一开始就会做专业预算。')}</p></div></div></details><details class="process-question"><summary>${t('How are mentoring and funding arranged?','导师与资金支持如何安排？')}</summary><div class="answer-body"><div class="detail-stack detail-grid2"><div class="detail-text mentor-local"><span class="pill">${t('CHINA-BASED','中国导师')}</span><h3>${t('Local understanding','更了解本地情境')}</h3><p>${t('Proposed profile: a China-based nonprofit or community practitioner. Chinese-led guidance on community needs, partner outreach and realistic local pilots.','拟议导师类型：在中国从事公益或社区实践的工作者。以中文为主，围绕社区需要、伙伴联系与可行的本地试点提供指导。')}</p></div><div class="detail-text mentor-international"><span class="pill">${t('INTERNATIONAL','国际导师')}</span><h3>${t('A wider perspective','打开更广阔的视角')}</h3><p>${t('Proposed profile: an experienced nonprofit founder or social-impact practitioner. English-led guidance on project scope, leadership and learning from pilots.','拟议导师类型：有经验的公益组织发起者或社会影响实践者。以英文为主，围绕项目范围、领导力与试点学习提供指导。')}</p></div></div><div class="guidance-copy"><h3>${t('How would guidance work?','导师指导如何进行？')}</h3><p>${t('<strong>Before the pilot:</strong> refine the problem, first activity, budget and achievable milestones. </p><p><strong>During the pilot:</strong> online kickoff, midpoint and final check-ins, with agreed communication between sessions to discuss obstacles and adjustments. </p><p><strong>After the pilot:</strong> review spending, participant feedback and learning, then discuss the next step.</p><p>Share mentor and language preferences in your application; named mentors and availability are not yet confirmed.','<strong>试点前：</strong>细化要解决的问题、第一次活动、预算与可实现的阶段目标。</p><p><strong>试点中：</strong>拟安排线上启动、中期和结束沟通，并约定期间的联系方式，讨论困难与调整。</p><p><strong>试点后：</strong>共同回顾支出、参与者反馈与学习，讨论下一步。</p><p>可在申请中表达导师与语言偏好；具体导师及可用性尚待确认。')}</p></div>${note()}<div class="detail-text"><h3>${t('How funding would work','资金如何发放')}</h3><p>${t('<strong>Before the pilot:</strong> 80–90% of the agreed grant.</p><p><strong>After completion:</strong> The remaining 10–20%, following a short spending and learning review.</p><p>A complementary split (for example, 80/20 or 90/10) and release conditions would be agreed before launch.','<strong>试点前：</strong>发放核定资助的80%–90%。</p><p><strong>完成后：</strong>提交简短支出与学习总结，发放剩余10%–20%。</p><p>启动前明确合计为100%的具体比例（如80/20或90/10）和发放条件。')}</p><p class="small muted">${t('Your initial estimate is one assessment input, not a grant guarantee. Final funding follows review and mentor-supported budget planning.','初步资金自评是资助评审依据之一，不代表一定获批。最终金额在审核及导师协助的预算规划后确定。')}</p></div></div></details><details class="process-question"><summary>${t('What happens after the pilot?','试点结束后需要做什么？')}</summary><div class="answer-body"><h3 class="spaced">${t('How we would review the pilot','如何回顾试点成果')}</h3><div class="detail-stack detail-grid3"><div class="detail-text"><h3>${t('Practical value','实际价值')}</h3><p>${t('Did the activity help address the stated problem or meet a need? Gather simple participant feedback.','是否回应了原本的问题或满足需求？收集简短参与者反馈。')}</p></div><div class="detail-text"><h3>${t('Participation','共同参与')}</h3><p>${t('Were the people affected and relevant partners involved in shaping or delivering the activity?','相关人群和伙伴是否共同参与设计或推动行动？')}</p></div><div class="detail-text"><h3>${t('Learning & potential','学习与后续潜力')}</h3><p>${t('What should change? Could a useful approach continue or be repeated elsewhere? Innovation can be explored where relevant; growth is not required.','学到了什么、应如何调整？有效做法能否持续或被复制推广？可视项目讨论创新性，不要求一定扩大。')}</p></div></div><h3>${t('Where could your next step lead?','下一步，你想走向哪里？')}</h3><p class="lead">${t('A pilot opens possibilities. Choose a path based on what you learn.','试点之后有多种可能，带着真实收获选择适合你的方向。')}</p><div class="detail-stack detail-grid3">${[['refresh',t('Refine or pause','调整或暂停'),t('Keep what you learned. Change the idea, or take a break.','保留收获，调整想法，也可以暂时停下来。')],['network',t('Continue locally','在本地继续'),t('Develop a useful action with peers and community partners.','与同伴和社区伙伴一起延续有价值的行动。')],['seed',t('Grow as a founder','向发起者成长'),t('Build on the pilot and explore relevant TRIIBE opportunities.','逐步发展自己的项目，了解适合的 TRIIBE 机会。')]].map(([i,a,b])=>`<div class="detail-text"><div class="line-icon">${icon(i)}</div><h3>${a}</h3><p>${b}</p>${i==='seed'?`<a class="link" href="#about">${t('Explore TRIIBE ↗','了解 TRIIBE ↗')}</a>`:''}</div>`).join('')}</div><p class="small muted">${t('Possible pathways, not automatic admission or continued funding.','以上为可能路径，不代表自动进入后续项目或持续获得资助。')}</p></div></details><div class="details-footer"><a class="link" href="#faq">${t('More frequently asked questions ↗','更多常见问题 ↗')}</a></div></div><div class="actions page-apply">${btn(t('Apply →','开始申请 →'),'#apply')}</div></div></section>`}
function toolPage(type){const rec=type==='rec';return `<section class="hero tool-hero"><div class="wrap hero-grid"><div><div class="eyebrow">${rec?t('Find your starting point','探索适合你的起点'):t('Plan your first experiment','规划第一次尝试')}</div><h1>${rec?t('What support<br>would help you begin?','什么支持，<br>能帮你迈出第一步？'):t('What could your<br>first idea cost?','你的第一个想法，<br>需要多少预算？')}</h1><p class="lead">${rec?t('Three quick questions to explore what you need. Optional and separate from your application.','三个简单问题，找到当前需要的支持。这是可选工具，与正式申请分开。'):t('Estimate essential costs at your own pace. No detailed budget is needed to apply.','慢慢估算第一次行动的必要开支。申请时无需提交详细预算。')}</p><button class="btn btn-primary" id="open-tool" aria-expanded="false" aria-controls="tool-panel">${rec?t('Start recommendation →','开始需求测试 →'):t('Open budget estimator →','打开预算估算 →')}</button></div><figure class="hero-art tool-art"><img src="${siteImage((rec?'hero':'market')+'.jpg')}" alt="${t('Illustrative youth project scene','青年项目场景插画')}"></figure></div></section><section class="section alt hidden" id="tool-panel"><div class="wrap"><div class="tool-heading"><h2>${rec?t('Find your next step','找到适合你的下一步'):t('Estimate the essentials','从必要开支开始')}</h2><button class="btn btn-outline" id="close-tool">${t('Close tool −','收起工具 −')}</button></div><iframe class="triibe-tool" id="planning-tool" title="${rec?t('Support recommendation','需求推荐'):t('Budget estimator','预算估算')}" data-src="tools.html?v=20261104-v53&lang=${lang}&tab=${type}" ></iframe></div></section><section class="section" id="project-examples"><div class="wrap"><div class="section-heading"><div><div class="eyebrow">${t('Illustrative project ideas','假设项目案例')}</div><h2>${rec?t('Small experiments.<br>Real possibilities.','从小实验里，<br>看见更多可能。'):t('See where the<br>money goes.','看看每一笔钱，<br>如何支持行动。')}</h2></div>${rec?'':`<p>${t('Example budgets, not quotes or funding guarantees. Use free and borrowed resources first.','示例预算，并非实际报价或资助承诺。请优先使用免费或可借用的资源。')}</p>`}</div>${rec?projectCards():budgetExamples()}</div></section>`}
function budgetExamples(){return `<div class="budget-examples">${projects.map(p=>{const total=p.rows.reduce((s,r)=>s+r[1]*r[2],0);return `<article class="budget-example"><img src="${siteImage(p.id+'.jpg')}" alt="${esc(pt(p.title))}" loading="lazy"><div class="budget-copy"><div class="budget-title"><h3>${pt(p.title)}</h3><strong>¥${total.toLocaleString()}</strong></div><p>${pt(p.desc)}</p><div class="cost-table">${p.rows.map(([a,q,u,why])=>`<div class="cost-line"><div><b>${pt(a)}</b><small>${pt(why)}</small></div><span>${q} × ¥${u}</span><strong>¥${(q*u).toLocaleString()}</strong></div>`).join('')}</div><div class="cost-total"><span>${t('Example total','示例合计')}</span><strong>¥${total.toLocaleString()}</strong></div></div></article>`}).join('')}</div><div class="notice spaced">${t('Start with the action → list essentials → estimate quantity × unit price. The proposed ¥1,000–5,000 range is not a spending target.','先确定行动 → 列出必要开支 → 计算数量 × 单价。拟议的¥1,000–5,000并不是必须花到的金额。')}</div>`}
function about(){return `${intro('TRIIBE',t('Backing the founder.<br>Opening a first door.','支持年轻发起者，<br>打开第一扇门。'),t('TRIIBE backs nonprofit founders under 30. This student concept explores an earlier entry point for young people in China.','TRIIBE支持30岁以下公益组织发起者。本学生概念探索面向中国年轻人、更早一步的参与入口。'))}<section class="section compact"><div class="wrap"><div class="pillars">${[['money',t('Funding','资金支持'),t('Resources to act','让行动拥有资源')],['people',t('Mentorship','导师指导'),t('Guidance to grow','在实践中获得指导')],['network',t('Connections','社群连接'),t('A community of founders','与年轻发起者建立联系')]].map(([i,a,b])=>`<div><div class="line-icon">${icon(i)}</div><h3>${a}</h3><p>${b}</p></div>`).join('')}</div><div class="actions">${btn(t('Explore TRIIBE’s official site ↗','访问TRIIBE官网 ↗'),'https://www.triibe.org/','outline')}</div><h2 class="spaced">${t('Founders in past TRIIBE cohorts','过往TRIIBE社群中的年轻发起者')}</h2><div class="grid3">${[['olivia','Olivia Zhang','Cancer Kids First',t('Activities and practical support for young cancer patients and families.','为年轻癌症患者及家庭提供活动与实际支持。')],['esha','Esha Venkat','NEST4US',t('Youth volunteering around hunger, learning and climate issues.','围绕饥饿、学习与气候议题开展青年志愿行动。')],['shrusti','Shrusti Amula','Rise N Shine Foundation',t('Food recovery and composting to address waste and food insecurity.','通过食物回收与堆肥应对浪费及食物不安全问题。')]].map(([photo,name,org,desc])=>`<article class="founder-card"><img src="${siteImage(photo+'.png')}" alt="${name}" loading="lazy"><div class="project-copy"><span class="pill">${name}</span><h3>${org}</h3><p>${desc}</p><a class="link" href="https://www.triibe.org/100" target="_blank" rel="noopener noreferrer">${t('Official founder profiles ↗','查看官方发起者介绍 ↗')}</a></div></article>`).join('')}</div><p class="small muted">${t('Official founder examples; no individual grant amounts or outcomes are implied.','以上为官方发起者案例，不推断个人所获资助金额或项目成果。')}</p><details class="editorial-details spaced"><summary>${t('Why explore China?','为什么探索中国？')}</summary><p>${t('Our design hypothesis: a locally grounded seed program could help TRIIBE reach young people before they establish an organization, understand their needs and identify emerging leaders. Expansion and partnerships remain proposals to validate with TRIIBE.','我们的设计假设是：立足本地的小额支持计划，可以帮助TRIIBE在年轻人创办机构之前与他们建立联系，了解需求，并识别潜在的青年发起者。拓展与合作仍需与TRIIBE共同验证。')}</p></details></div></section><section class="section alt"><div class="wrap"><div class="eyebrow">${t('A proposed collaboration','拟议合作结构')}</div><h2>TRIIBE × ${t('Shanghai United Foundation','上海联劝公益基金会')}</h2><div class="collaboration-map"><div class="collab-row"><article class="collab-node tinted"><h3>TRIIBE</h3><p>${t('Leadership framework · Tools · Potential mentors','领导力框架 · 实践工具 · 潜在导师连接')}</p></article><article class="collab-node tinted"><h3>${t('Shanghai United Foundation','上海联劝公益基金会')}</h3><p>${t('Explore local delivery · Resources · Compliance arrangements','探索本地落地 · 资源连接 · 合规安排')}</p></article></div><div class="collab-connector"><span>↓</span><p>${t('Joint design, coordination & evaluation (proposed)','共同设计、协调与评估（拟议）')}</p><span>↓</span></div><article class="collab-node program"><h3>${t('The Next Step pilot program','The Next Step 试点项目')}</h3><p>${t('Applications · Optional needs tools · Funding & mentor matching · Pilot guidance','申请 · 可选需求工具 · 资助与导师匹配 · 试点指导')}</p></article><div class="collab-connector single"><p>${t('↕ Local recruitment & delivery support','↕ 本地招募与落地支持')}</p></div><div class="collab-row"><article class="collab-node"><h3>${t('Universities / campus groups','高校／校园社团')}</h3><p>${t('Recruitment · Outreach · Campus resources','招募 · 宣传 · 校园资源')}</p></article><article class="collab-node"><h3>${t('Local nonprofits','本地公益机构')}</h3><p>${t('Community needs · Practical advice · Pilot settings','社区需要 · 实践建议 · 试点场景')}</p></article></div><div class="collab-connector single" aria-hidden="true">↓</div><article class="collab-node youth"><h3>${t('Young people & project teams','青年与项目团队')}</h3><p>${t('Share an idea → Receive support → Test a pilot → Reflect & grow','分享想法 → 获得支持 → 尝试试点 → 总结与成长')}</p></article></div>${note()}</div></section>`}
const faqs=()=>[[t('Who is this for?','谁可以参与？'),t('Young people aged 18–30 in China with an interest in social impact. You do not need to have founded an organization. Final eligibility would be confirmed by organizers.','面向中国18–30岁、关心公益或社会议题的年轻人，不需要已创办机构。最终资格由实际项目组织方确认。')],[t('Do I need a complete plan?','需要准备完整计划吗？'),t('No. One short idea about what you want to try and who it helps is enough for the practice application.','不需要。练习申请只需简短说明你想尝试什么、想帮助谁。')],[t('How much funding could I request?','可以申请多少资助？'),t('The proposed range is ¥1,000–5,000. Choose an approximate amount, “Not sure yet” or “Guidance only.” These are not guaranteed grants.','拟议范围为¥1,000–5,000。可选择大致金额、“还不确定”或“暂时只需要指导”。这不是资助承诺。')],[t('Do I have to complete the planning tools?','必须完成需求推荐和预算估算吗？'),t('No. Both tools are optional and separate from the application. A detailed budget is not required at this stage.','不需要。两个工具均为可选，且与申请分开。初次申请无需详细预算。')],[t('Can I choose a mentor?','可以选择导师吗？'),t('You can state a preference for a China-based or international mentor and Chinese, English or bilingual guidance. Matching depends on availability.','可以表达中国或国际导师偏好，以及中文、英文或双语指导偏好。实际匹配取决于导师可用性。')],[t('When will I hear back?','提交后多久收到回复？'),t('The proposed timeline is an initial reply within 5 working days, a conversation within 10 if needed, and a decision or progress update within 15, measured from receipt. Weekends and public holidays are excluded. This local demo sends nothing and has no real reply.','拟议时限为：收到申请起5个工作日内初步回复，10个工作日内按需沟通，15个工作日内告知结果或进展，不含周末与法定节假日。当前本地演示不会发送申请或收到真实回复。')],[t('How long is the pilot?','试点持续多久？'),t('A proposed 2–3 months, with scope, costs and mentor check-ins agreed before the start.','拟为2–3个月，开始前共同确认范围、费用与导师沟通安排。')],[t('What if I pause after the pilot?','试点后不继续可以吗？'),t('Yes. Learning, refining or pausing can all be useful outcomes. Continued funding or admission to other programs is not automatic.','可以。学习、调整与暂停都是有价值的结果。后续资助或进入其他项目并非自动获得。')],[t('How is funding assessed and released?','资助如何评审和发放？'),t('Your funding estimate, purpose and necessity are reviewed alongside your idea and a conversation. Final budgets are refined after screening. The proposed release is 80–90% upfront and the remaining 10–20% after completion; the exact split and conditions are agreed before launch.','结合想法、资金自评、用途必要性与沟通进行审核，初筛后再完善预算。拟在启动前发放80%–90%，完成后发放剩余10%–20%，具体配比与条件在启动前约定。')],[t('Is this an official application portal?','这是正式申请网站吗？'),t('No. This student concept explores a possible collaboration. Applications stay on your device and are not sent to TRIIBE or Shanghai United Foundation.','不是。这是探索拟议合作的学生概念原型，申请内容仅在设备上处理，不会发送给TRIIBE或联劝。')]];
const faq=()=>`${intro(t('A little clarity','开始前，多一点了解'),t('Questions before<br>you begin?','开始之前，<br>你可能想知道。'),t('The essentials, without the overwhelm.','关于支持、预算、导师与申请的简明回答。'))}<section class="section compact"><div class="wrap faq-wrap">${faqs().map(([q,a],i)=>`<details class="faq-item" ${i===0?'open':''}><summary>${q}</summary><p>${a}</p></details>`).join('')}<div class="spaced"><h3>${t('Proposed response timeline','拟议回复时限')}</h3>${timeline()}</div></div></section>`;
function contact(){return `${intro(t('Official channels','官方联系渠道'),t('Let’s connect.','保持联系。'),t('Public organization contacts for general or partnership enquiries. These are not a confirmed help desk for this student concept.','以下为机构公开咨询与合作渠道，并非本学生概念已设立的项目客服。'))}<section class="section compact"><div class="wrap grid2"><article class="card contact-card"><div class="eyebrow">01 / TRIIBE</div><h2>${t('Partnership enquiries','合作咨询')}</h2><p>${t('Official TRIIBE enquiries and collaboration questions.','TRIIBE机构咨询与合作事项。')}</p><p><a class="contact-link" href="mailto:partnerships@triibe.org">partnerships@triibe.org ↗</a></p><div class="actions">${btn(t('Official Contact Page ↗','官方联系页面 ↗'),'https://www.triibe.org/contact','outline')}</div></article><article class="card contact-card"><div class="eyebrow">02 / ${t('Shanghai United Foundation','上海联劝公益基金会')}</div><h2>${t('Enquiries & collaboration','咨询与合作')}</h2><p class="small muted">${t('General enquiries','一般咨询')}</p><p><a class="contact-link" href="mailto:infosh@lianquan.org">infosh@lianquan.org ↗</a></p><p class="small muted">${t('Corporate & public fundraising cooperation','企业合作与公募合作')}</p><p><a class="contact-link" href="mailto:dkh@lianquan.org">dkh@lianquan.org ↗</a></p><p class="small muted">${t('Telephone','电话')}</p><p><a class="contact-link" href="tel:+862160146234">+86 21 60146234 ↗</a></p><p class="small muted">${t('Weekdays 09:30–17:30, China time','工作日09:30–17:30，中国时间')}</p><div class="actions">${btn(t('Official Contact Page ↗','官方联系页面 ↗'),'https://www.lianquan.org.cn/','outline')}</div><details class="faq-item"><summary>${t('WeChat & official channels','微信与官方渠道')}</summary><p>${t('WeChat official account: 联劝公益. See the official website for current channels. A public WeCom contact has not been verified.','微信公众号：联劝公益。最新渠道请以官网为准，尚未核实公开企业微信联系方式。')}</p></details></article></div><div class="wrap spaced">${note()}</div></section>`}
let draft={},submitted=false;try{draft=JSON.parse(localStorage.getItem('triibe-v4-draft')||'{}')}catch{}
function capture(){const f=$('#application');if(!f)return;for(const el of f.elements)if(el.name)draft[el.name]=el.type==='checkbox'?el.checked:el.value;}
const field=(name,label)=>`<label class="form-field"><span>${label} *</span><input name="${name}" maxlength="80" required value="${esc(draft[name])}" autocomplete="off"></label>`;
const select=(name,label,options,required=false)=>`<label class="form-field"><span>${label}${required?' *':''}</span><select name="${name}" ${required?'required':''}>${options.map(([v,a])=>`<option value="${v}" ${String(draft[name]??'')===v?'selected':''}>${a}</option>`).join('')}</select></label>`;
function apply(){return `${intro(t('Your short application','一页简短申请'),t('Your idea.<br>One first step.','一个想法，<br>从第一步开始。'),t('Share your idea and a short initial plan and support self-assessment. No business plan, recommendation test or itemized budget required.','分享想法，并完成简短的初步计划与支持自评，无需商业计划、需求测试或逐项预算。'))}<section class="section compact"><div class="wrap application-wrap"><div class="application-time"><span class="eyebrow">${t('Know what comes next','先了解之后会发生什么')}</span><p><strong>${t('2–3 month pilot','2–3个月试点')}</strong> · ${t('Proposed initial reply within 5 working days','拟在5个工作日内初步回复')}</p><details><summary>${t('See response timing','查看回复时限')}</summary>${timeline()}</details></div><div class="notice">${t('Practice application only. Nothing is sent. You may save a draft on this device or download a copy.','仅为练习申请，不会实际发送。你可以在本设备保存草稿，或下载副本。')}</div><form id="application" class="card spaced"><div class="grid2">${field('nickname',t('Nickname','昵称'))}${select('age',t('Age','年龄'),[['',t('Choose age','选择年龄')],...Array.from({length:13},(_,i)=>[String(i+18),String(i+18)])],true)}</div>${field('location',t('City / region','城市／地区'))}<label class="form-field"><span>${t('What would you like to try, and who is it for?','你想尝试什么？想帮助谁？')} *</span><textarea required maxlength="300" name="idea" placeholder="${t('A sentence or two is enough.','一两句话就好。')}">${esc(draft.idea)}</textarea><small class="muted">${t('Up to 300 characters','最多300字')}</small></label><label class="form-field"><span>${t('What is your main challenge right now?','目前主要遇到什么困难？')}</span><textarea name="challenge" maxlength="200" placeholder="${t('A short answer is enough; unsure is okay.','简短说明即可，还不确定也可以。')}">${esc(draft.challenge)}</textarea></label><fieldset class="initial-plan"><legend>${t('Initial Plan & Support','初步计划与支持自评')}</legend><p class="small muted">${t('This helps reviewers assess fit and funding needs. Give an honest first estimate; you can refine it with a mentor after screening.','用于评估项目适配度与资助需求。请按当前理解如实估计，通过初筛后可与导师完善。')}</p>${select('duration',t('How long might your first activity take?','你预计第一次活动需要多长时间？'),[['Unsure',t('Not sure yet','还不确定')],['day',t('One day','一天')],['weeks',t('2–4 weeks','2–4周')],['months',t('2–3 months','2–3个月')]])}<p class="small muted">${t('A first activity may be shorter than the overall 2–3 month pilot.','第一次活动可以短于整体2–3个月的试点周期。')}</p><div class="grid2">${select('budget',t('Funding needed','希望申请的资助'),[['Unsure',t('Not sure yet','还不确定')],['1000','¥1,000'],['2000','¥2,000'],['3000','¥3,000'],['5000','¥5,000'],['0',t('Guidance only for now','暂时只需要指导')]])}</div><label class="form-field"><span>${t('What would you use the funding for and why?','这笔钱主要准备花在哪里？为什么需要？')} *</span><textarea required name="fundingUse" maxlength="300" placeholder="${t('For example: collection bins, publicity materials and transport for donated clothes. If unsure or seeking guidance only, tell us what help you need.','例如：收集箱、宣传材料及运输旧衣的费用。若还不确定或只需要指导，请说明希望获得什么帮助。')}">${esc(draft.fundingUse)}</textarea><small class="muted">${t('A brief explanation is enough; no itemized budget needed.','简短说明即可，无需逐项计算详细预算。')}</small></label></fieldset><div class="grid2">${select('mentor',t('Mentor preference','导师偏好'),[['Either',t('Either is fine','都可以')],['China',t('China-based mentor','中国导师')],['International',t('International mentor','国际导师')]])}</div>${select('language',t('Preferred guidance language','指导语言偏好'),[['Chinese',t('Chinese','中文')],['English',t('English','英文')],['Either',t('Either / bilingual','都可以／双语')]])}<p class="small muted">${t('Preferences inform matching; specific mentors and funding are not guaranteed.','偏好用于后续匹配，不保证特定导师或资助。')}</p><label class="check"><input type="checkbox" name="ack" required ${draft.ack?'checked':''}><span>${t('I understand this is a local practice application, not a real submission.','我理解这是本地练习申请，不是正式提交。')}</span></label><div class="actions"><button type="submit" class="btn btn-primary">${t('Complete practice application →','完成练习申请 →')}</button><button type="button" class="btn btn-outline" id="save-draft">${t('Save draft','保存草稿')}</button><button type="button" class="text-button" id="clear-draft">${t('Clear draft','清除草稿')}</button></div><p id="draft-status" role="status" class="small"></p><div id="apply-result" aria-live="polite">${submitted?success():''}</div></form></div></section>`}
function success(){return `<div class="result"><h3>${t('Your first step is ready.','你的第一步，准备好了。')}</h3><p>${t('Nothing has been sent. Download a copy to keep your practice application.','尚未实际发送。你可以下载副本，保留这份练习申请。')}</p><button type="button" class="btn btn-outline" id="download-draft">${t('Download a copy ↓','下载申请副本 ↓')}</button></div>`}
function downloadDraft(){capture();const pairs=[['nickname',t('Nickname','昵称')],['age',t('Age','年龄')],['location',t('City / region','城市／地区')],['idea',t('Idea','想法')],['challenge',t('Current challenge','目前困难')],['duration',t('First activity duration','第一次活动时长')],['budget',t('Funding needed','资助需求')],['fundingUse',t('Funding use and reason','资金用途与原因')],['mentor',t('Mentor preference','导师偏好')],['language',t('Guidance language','指导语言')]];const content='THE NEXT STEP — '+t('Practice application','练习申请')+'\n\n'+pairs.map(([k,l])=>{const el=document.querySelector('#application select[name="'+k+'"]');return l+': '+(el?el.options[el.selectedIndex].text:(draft[k]||'—'))}).join('\n\n')+'\n\n'+t('Local copy. Not submitted.','本地副本，尚未提交。');const u=URL.createObjectURL(new Blob(['\uFEFF'+content],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download='The-Next-Step-Application.txt';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
const pages={home,how,about,faq,contact,recommendation:()=>toolPage('rec'),budget:()=>toolPage('budget'),apply};
function pageKey(){const key=location.hash.slice(1).split('?')[0];return pages[key]?key:'home'}
function shell(key){document.documentElement.lang=lang==='zh'?'zh-CN':'en';$('#site-header').innerHTML=`<a class="brand" href="#home"><b>TRIIBE <i>×</i> 联劝</b><span>THE NEXT STEP · ${t('CONCEPT','合作概念')}</span></a><button class="mobile-toggle" id="menu-toggle" aria-label="${t('Open navigation','打开导航')}" aria-expanded="false" aria-controls="nav"><span></span><span></span><span></span></button><nav id="nav" aria-label="${t('Main navigation','主导航')}"><a href="#home" ${key==='home'?'aria-current="page"':''}>${t('Home','首页')}</a><a href="#how" ${key==='how'?'aria-current="page"':''}>${t('How It Works','如何参与')}</a><div class="nav-dropdown"><button id="next-menu" aria-expanded="false" aria-controls="next-links" class="nav-label ${['recommendation','budget'].includes(key)?'active':''}">${t('Find My Next Step','探索下一步')} <span>⌄</span></button><div class="dropdown-links" id="next-links" hidden><a href="#recommendation" ${key==='recommendation'?'aria-current="page"':''}>${t('Support Recommendation','需求推荐')}</a><a href="#budget" ${key==='budget'?'aria-current="page"':''}>${t('Budget Estimator','预算估算')}</a></div></div><a href="#about" ${key==='about'?'aria-current="page"':''}>${t('About TRIIBE','关于TRIIBE')}</a><a href="#faq" ${key==='faq'?'aria-current="page"':''}>${t('FAQ','常见问题')}</a></nav><div class="header-tools"><button class="language-toggle" id="language-toggle" aria-label="${t('Switch to Chinese','Switch to English')}">${t('中文','EN')}</button>${btn(t('Apply ↗','申请支持 ↗'),'#apply')}</div>`;$('#site-footer').innerHTML=`<span>THE NEXT STEP · TRIIBE × ${t('Shanghai United Foundation','上海联劝公益基金会')}</span><span>${t('Student concept · Proposed collaboration · No real submissions','学生概念 · 拟议合作 · 不接收正式申请')}</span>`;document.querySelector('.contact-float')?.remove();document.body.insertAdjacentHTML('beforeend',`<a class="contact-float" href="#contact" aria-label="${t('Contact','联系我们')}">${icon('mail')}<span>${t('Contact','联系')}</span></a>`);$('#menu-toggle').onclick=()=>{const open=$('#nav').classList.toggle('open');$('#menu-toggle').setAttribute('aria-expanded',String(open))};$('#next-menu').onclick=()=>{const open=$('#next-menu').getAttribute('aria-expanded')!=='true';$('#next-menu').setAttribute('aria-expanded',String(open));$('#next-links').hidden=!open};$('#language-toggle').onclick=()=>{capture();lang=lang==='zh'?'en':'zh';try{localStorage.setItem('triibe-language',lang)}catch{}render(false)};}
const openTools={rec:false,budget:false};let activeTool=null;const toolState={a:[null,null,null],mode:'estimate',costs:[]};
function render(resetScroll=true){capture();const key=pageKey(),oldScroll=window.scrollY;shell(key);app.innerHTML=pages[key]();activeTool=null;if(key==='recommendation'||key==='budget')setupTool(key==='recommendation'?'rec':'budget');if(key==='apply')setupApply();if(resetScroll){window.scrollTo({top:0,behavior:'instant'});app.focus({preventScroll:true});if(location.hash.includes('section=examples'))requestAnimationFrame(()=>$('#project-examples')?.scrollIntoView({behavior:'instant',block:'start'}))}else window.scrollTo({top:oldScroll,behavior:'instant'});}
function setupTool(type){const panel=$('#tool-panel'),toggle=$('#open-tool'),frame=$('#planning-tool');function open(shouldScroll){openTools[type]=true;panel.classList.remove('hidden');toggle.setAttribute('aria-expanded','true');if(!frame.getAttribute('src')){activeTool=frame;frame.src=frame.dataset.src;frame.addEventListener('load',()=>{frame.contentWindow.postMessage({type:'triibe-restore',state:toolState,lang,tab:type},'*')},{once:true})}if(shouldScroll)panel.scrollIntoView({behavior:'smooth',block:'start'})}toggle.onclick=()=>open(true);$('#close-tool').onclick=()=>{openTools[type]=false;panel.classList.add('hidden');toggle.setAttribute('aria-expanded','false');toggle.focus()};if(openTools[type])open(false)}
window.addEventListener('message',e=>{if(!activeTool||e.source!==activeTool.contentWindow)return;const d=e.data;if(d?.type==='triibe-tool-height'&&Number.isFinite(d.height))activeTool.style.height=Math.min(15000,Math.max(600,d.height+15))+'px';if(d?.type==='triibe-tool-state'&&d.state){Object.assign(toolState,d.state)}if(d?.type==='triibe-route')location.hash=d.route==='apply'?'#apply':d.route==='budget'?'#budget':'#recommendation'});
function setupApply(){const f=$('#application');f.oninput=capture;f.onchange=capture;$('#save-draft').onclick=()=>{capture();try{localStorage.setItem('triibe-v4-draft',JSON.stringify(draft));$('#draft-status').textContent=t('Saved on this device only.','草稿仅保存在本设备。')}catch{$('#draft-status').textContent=t('Storage unavailable. Download your copy instead.','浏览器无法保存，请完成练习后下载副本。')}};$('#clear-draft').onclick=()=>{draft={};submitted=false;try{localStorage.removeItem('triibe-v4-draft')}catch{}f.reset();for(const el of f.elements)if(el.name){if(el.type==='checkbox')el.checked=false;else if(el.tagName==='SELECT')el.selectedIndex=0;else el.value=''}$('#apply-result').innerHTML='';$('#draft-status').textContent=t('Draft cleared.','草稿已清除。')};f.onsubmit=e=>{e.preventDefault();if(!f.reportValidity())return;capture();submitted=true;$('#apply-result').innerHTML=success();$('#download-draft').onclick=downloadDraft;$('#apply-result').scrollIntoView({behavior:'smooth',block:'nearest'})};if($('#download-draft'))$('#download-draft').onclick=downloadDraft;}
document.addEventListener('click',e=>{if(!e.target.closest('.nav-dropdown')&&$('#next-links')){$('#next-links').hidden=true;$('#next-menu').setAttribute('aria-expanded','false')}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#next-links').hidden=true;$('#next-menu').setAttribute('aria-expanded','false');$('#nav').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false')}});window.addEventListener('hashchange',()=>render());render();
